    boost::algorithm::replace_all(markdown, "http(s)?://([A-Za-z0-9+&/%=\\-\\.\\_\\~\\!\\'\\(\\)\\*,\\@\\(\\)@]*)", "<a href=\"\\1\">\\1</a>");

